import functools
class Solution:
    def makeStringGood(self, s: str) -> int:
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        n = len(s)
        best = n
        for m in range(1, n + 1):
            @functools.lru_cache(maxsize=None)
            def dfs(i, j):
                if i == 26:
                    return 0
                have = cnt[i] + j
                res = min(have + dfs(i + 1, 0), abs(have - m) + dfs(i + 1, 0))
                for t in range(1, have + 1):
                    res = min(res, min(have, t + max(0, have - t - m)) + dfs(i + 1, t))
                return res
            best = min(best, dfs(0, 0))
        return best

