class Solution {
public:
    int makeStringGood(string s) {
        vector<long long> cnt(26, 0);
        for (char c : s) cnt[c - 'a']++;
        int n = s.size();
        int best = n;
        for (int m = 1; m <= n; m++) {
            vector<vector<long long>> memo(27, vector<long long>(n + 1, -1));
            function<long long(int,int)> dfs = [&](int i, int j) -> long long {
                if (i == 26) return 0;
                auto &me = memo[i][j];
                if (me != -1) return me;
                long long have = cnt[i] + j, res = LLONG_MAX;
                res = min(res, have + dfs(i + 1, 0));
                res = min(res, llabs(have - m) + dfs(i + 1, 0));
                for (long long t = 1; t <= have && t <= n; t++) {
                    long long conv = min(have, t + max(0LL, have - t - m));
                    res = min(res, conv + dfs(i + 1, (int)t));
                }
                return me = res;
            };
            best = (int)min((long long)best, dfs(0, 0));
        }
        return best;
    }
};

