class Solution {
    int[] cnt;
    int n, m;
    long[][] memo;

    public int makeStringGood(String s) {
        cnt = new int[26];
        for (char c : s.toCharArray()) cnt[c - 'a']++;
        n = s.length();
        int best = n;
        for (m = 1; m <= n; m++) {
            memo = new long[27][n + 1];
            for (long[] row : memo) java.util.Arrays.fill(row, -1);
            best = (int) Math.min(best, dfs(0, 0));
        }
        return best;
    }

    private long dfs(int i, int j) {
        if (i == 26) return 0;
        if (memo[i][j] != -1) return memo[i][j];
        long have = cnt[i] + j;
        long res = Math.min(have + dfs(i + 1, 0), Math.abs(have - m) + dfs(i + 1, 0));
        for (long t = 1; t <= have && t <= n; t++) {
            long conv = Math.min(have, t + Math.max(0, have - t - m));
            res = Math.min(res, conv + dfs(i + 1, (int) t));
        }
        return memo[i][j] = res;
    }
}

