                for j in range(n + 1):
                    v = dp[j]
                    if v >= best:
                        continue
                    have = c + j
                    if v + have < ndp[0]:
                        ndp[0] = v + have
                    d = v + abs(have - m)
                    if d < ndp[0]:
                        ndp[0] = d
                    base = v + have
                    hi = min(have, n)
