class Solution {
public:
    int makeStringGood(string s) {
        vector<long long> cnt(26, 0);
        for (char c : s) cnt[c - 'a']++;
        int n = s.size();
        const long long INF = LLONG_MAX / 4;
        int best = n;
        for (int m = 1; m <= n; m++) {
            vector<long long> dp(n + 1, INF), ndp(n + 1);
            dp[0] = 0;
            for (int i = 0; i < 26; i++) {
                fill(ndp.begin(), ndp.end(), INF);
                long long c = cnt[i];
                for (int j = 0; j <= n; j++) {
                    long long v = dp[j];
                    if (v >= best) continue;
                    long long have = c + j;
                    ndp[0] = min(ndp[0], v + have);
                    ndp[0] = min(ndp[0], v + llabs(have - m));
                    long long base = v + have;
                    long long hi = min(have, (long long)n);
                    for (long long t = 1; t <= hi; t++) {
                        long long val = min(base, v + t + max(0LL, have - t - m));
                        if (val < ndp[t]) ndp[t] = val;
                    }
                }
                swap(dp, ndp);
            }
            for (int j = 0; j <= n; j++) best = (int)min((long long)best, dp[j]);
        }
        return best;
    }
};

