class Solution {
    public int makeStringGood(String s) {
        long[] cnt = new long[26];
        for (char c : s.toCharArray()) cnt[c - 'a']++;
        int n = s.length();
        final long INF = Long.MAX_VALUE / 4;
        int best = n;
        for (int m = 1; m <= n; m++) {
            long[] dp = new long[n + 1], ndp = new long[n + 1];
            java.util.Arrays.fill(dp, INF);
            dp[0] = 0;
            for (int i = 0; i < 26; i++) {
                java.util.Arrays.fill(ndp, INF);
                long c = cnt[i];
                for (int j = 0; j <= n; j++) {
                    long v = dp[j];
                    if (v >= best) continue;
                    long have = c + j;
                    ndp[0] = Math.min(ndp[0], v + have);
                    ndp[0] = Math.min(ndp[0], v + Math.abs(have - m));
                    long base = v + have;
                    long hi = Math.min(have, n);
                    for (long t = 1; t <= hi; t++) {
                        long val = Math.min(base, v + t + Math.max(0, have - t - m));
                        if (val < ndp[(int) t]) ndp[(int) t] = val;
                    }
                }
                long[] tmp = dp; dp = ndp; ndp = tmp;
            }
            for (int j = 0; j <= n; j++) best = (int) Math.min(best, dp[j]);
